steps.script:
function transform(ctx) {
  var MAP = { "移动": "cmcc", "联通": "unicom", "电信": "telecom" };
  var isp = (ctx.isp || "").trim();
  var s = isp ? (MAP[isp] !== undefined ? MAP[isp] : (isp.charAt(0) === "@" ? isp : "")) : "";
  var full = (ctx.username || "") + (s ? "@" + s : "");
  return { ua: url_encode(full), ep: url_encode(ctx.password || "") };
}
